data=json.load(open(P,encoding="utf-8"))
have={g["pattern"] for g in data}
n=len(data)
for lv,pt,ja,ex,egs in G:
    if pt in have: continue
    n+=1
    data.append({"id":f"g-{n:03d}","level":lv,"pattern":pt,"ja":ja,"explanation":ex,"examples":[{"ko":a,"ja":b} for a,b in egs]})
json.dump(data,open(P,"w",encoding="utf-8"),ensure_ascii=False,indent=2)
print("grammar total",len(data), {l:sum(1 for g in data if g["level"]==l) for l in (1,2,3)})
